<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
const props = defineProps({ cog: Object, canEdit: Boolean });
const canvas = ref(null); const signing = ref(false); const signature = ref('');
const start = (event) => { if (!props.canEdit || props.cog.signature) return; signing.value = true; const rect = canvas.value.getBoundingClientRect(); const context = canvas.value.getContext('2d'); context.beginPath(); context.moveTo(event.clientX - rect.left, event.clientY - rect.top); };
const draw = (event) => { if (!signing.value) return; const rect = canvas.value.getBoundingClientRect(); const context = canvas.value.getContext('2d'); context.lineTo(event.clientX - rect.left, event.clientY - rect.top); context.stroke(); };
const end = () => { if (signing.value) signature.value = canvas.value.toDataURL('image/png'); signing.value = false; };
const clear = () => { signature.value = ''; canvas.value?.getContext('2d').clearRect(0, 0, canvas.value.width, canvas.value.height); };
const sign = () => useForm({ signature: signature.value }).post(route('miri-cogs.sign', props.cog.id), { preserveScroll: true });
</script>
<template><Head title="Miri COG"/><AuthenticatedLayout><section class="space-y-6"><header class="flex flex-wrap items-end justify-between gap-4 rounded-[2rem] border border-[#d8e7d4] bg-white p-7 shadow-sm"><div><p class="text-xs font-bold uppercase tracking-[.25em] text-[#4f9f4a]">Digital COG</p><h1 class="mt-2 text-3xl font-bold text-[#234222]">{{ cog.cog_no }}</h1><p class="mt-2 text-sm text-[#60745d]">{{ cog.movement_type }} · {{ cog.status }}</p></div><div class="flex gap-2"><a :href="route('miri-cogs.pdf', cog.id)" class="rounded-xl bg-[#234222] px-4 py-3 text-sm font-bold text-white">Download PDF</a><Link :href="route('miri-cogs.index')" class="btn">Back to COG register</Link></div></header><section class="rounded-[2rem] border border-[#d8e7d4] bg-white p-6 shadow-sm"><dl class="grid gap-5 text-sm sm:grid-cols-2 lg:grid-cols-4"><div><dt class="text-xs font-bold uppercase text-slate-500">Movement</dt><dd class="mt-1 font-semibold">{{ cog.movement_type }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-500">Document date</dt><dd class="mt-1">{{ cog.document_date }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-500">From</dt><dd class="mt-1">{{ cog.from_location || '-' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-500">To</dt><dd class="mt-1">{{ cog.to_location || '-' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-500">Receiver</dt><dd class="mt-1">{{ cog.receiver_name || '-' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-500">Issued by</dt><dd class="mt-1">{{ cog.issued_by_name }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-500">Created by</dt><dd class="mt-1">{{ cog.creator?.name || '-' }}</dd></div><div><dt class="text-xs font-bold uppercase text-slate-500">Remarks</dt><dd class="mt-1">{{ cog.remarks || '-' }}</dd></div></dl></section><section class="overflow-hidden rounded-[2rem] border border-[#d8e7d4] bg-white shadow-sm"><div class="border-b border-slate-100 px-6 py-4"><h2 class="font-bold text-[#234222]">COG items</h2></div><div class="overflow-x-auto"><table class="table"><thead><tr><th>Type</th><th>Identifier</th><th>Description</th><th>Current location</th><th>Quantity</th><th>Remarks</th></tr></thead><tbody><tr v-for="item in cog.items" :key="item.id"><td>{{ item.item_type }}</td><td class="font-bold">{{ item.identifier || '-' }}</td><td>{{ item.description || '-' }}</td><td>{{ item.current_location || '-' }}</td><td>{{ item.quantity }} {{ item.unit || '' }}</td><td>{{ item.remarks || '-' }}</td></tr></tbody></table></div></section><section v-if="canEdit && !cog.signature" class="rounded-[2rem] border border-[#d8e7d4] bg-white p-6 shadow-sm"><h2 class="font-bold text-[#234222]">Digital receiver signature</h2><p class="mt-1 text-sm text-slate-500">Sign below to mark this COG as signed. The signature will be included in the PDF.</p><canvas ref="canvas" width="700" height="180" class="mt-4 h-44 w-full touch-none rounded-xl border border-dashed border-[#aac4a4] bg-[#fbfdfb]" @pointerdown="start" @pointermove="draw" @pointerup="end" @pointerleave="end"/><div class="mt-3 flex gap-2"><button type="button" class="btn" @click="clear">Clear</button><button type="button" class="rounded-xl bg-[#234222] px-4 py-2 text-sm font-bold text-white disabled:opacity-50" :disabled="!signature" @click="sign">Sign COG</button></div></section><section v-else-if="cog.signature" class="rounded-[2rem] border border-emerald-200 bg-emerald-50/40 p-6"><h2 class="font-bold text-emerald-900">Signed COG</h2><img :src="cog.signature" alt="Digital signature" class="mt-3 max-h-24 max-w-xs"/><p class="mt-2 text-xs text-slate-500">Signed {{ cog.signed_at || '' }}</p></section></section></AuthenticatedLayout></template>
